# --------------------------------------------------------------------------
#  CONSOLA: banner PORTE gigante + carga + clave
# --------------------------------------------------------------------------
function Show-PorteBanner {
    Clear-Host
    $font = @{
        'P' = @('#### ', '#   #', '#   #', '#### ', '#    ', '#    ', '#    ')
        'O' = @(' ### ', '#   #', '#   #', '#   #', '#   #', '#   #', ' ### ')
        'R' = @('#### ', '#   #', '#   #', '#### ', '# #  ', '#  # ', '#   #')
        'T' = @('#####', '  #  ', '  #  ', '  #  ', '  #  ', '  #  ', '  #  ')
        'E' = @('#####', '#    ', '#    ', '#### ', '#    ', '#    ', '#####')
    }
    $colors = @('Blue', 'Blue', 'Cyan', 'Cyan', 'Cyan', 'White', 'White')
    $block  = [string][char]0x2588
    Write-Host ''
    for ($r = 0; $r -lt 7; $r++) {
        $line = '   '
        foreach ($ch in 'P', 'O', 'R', 'T', 'E') {
            foreach ($c in $font[$ch][$r].ToCharArray()) {
                if ($c -eq '#') { $line += ($block + $block) } else { $line += '  ' }
            }
            $line += '   '
        }
        Write-Host $line -ForegroundColor $colors[$r]
        Write-Host $line -ForegroundColor $colors[$r]
    }
    Write-Host ''
    Write-Host '   PXTDETECTED.IA  //  Forensic Scanner  v' -NoNewline -ForegroundColor Cyan
    Write-Host $script:AppVer -ForegroundColor White
    Write-Host ''
    $steps = @('Inicializando nucleo', 'Cargando modulos de deteccion', 'Cargando firmas de cheats', 'Preparando motor visual', 'Verificando entorno')
    $empty = [string][char]0x2591
    for ($i = 0; $i -le 100; $i += 2) {
        $msg = $steps[[math]::Min([int][math]::Floor($i / 20), 4)]
        $w = 44
        $f = [int][math]::Floor($w * $i / 100)
        $bar = ($block * $f) + ($empty * ($w - $f))
        Write-Host ("`r   [{0}] {1,3}%  {2}" -f $bar, $i, $msg.PadRight(34)) -NoNewline -ForegroundColor Cyan
        Start-Sleep -Milliseconds 40
    }
    Write-Host ''
}

function Test-PorteKey {
    for ($try = 1; $try -le 3; $try++) {
        Write-Host ''
        Write-Host '   Ingresa la clave de activacion y presiona ENTER:' -ForegroundColor Cyan
        $sec  = Read-Host '   CLAVE' -AsSecureString
        $bstr = [Runtime.InteropServices.Marshal]::SecureStringToBSTR($sec)
        try   { $plain = [Runtime.InteropServices.Marshal]::PtrToStringBSTR($bstr) }
        finally { [Runtime.InteropServices.Marshal]::ZeroFreeBSTR($bstr) }
        $plain = ($plain -replace '\s+', '')
        $sha   = [Security.Cryptography.SHA256]::Create()
        $hash  = ([BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes($plain)))).Replace('-', '').ToLower()
        if ($hash -eq $script:KeyHash) {
            Write-Host '   [OK] Clave valida. Iniciando PXTDETECTED.IA ...' -ForegroundColor Green
            Start-Sleep -Milliseconds 700
            return $true
        }
        Write-Host ''
        Write-Host '   [ERROR] CLAVE INVALIDA - la aplicacion no se puede iniciar.' -ForegroundColor Red
        if ($try -lt 3) { Write-Host ("   Intento {0} de 3." -f $try) -ForegroundColor DarkYellow }
    }
    Write-Host ''
    Write-Host '   [ACCESO DENEGADO] Se agotaron los intentos.' -ForegroundColor Red
    return $false
}

# --------------------------------------------------------------------------
#  CAMPO DE PARTICULAS / NODOS (C# compilado, dibuja con WPF)
# --------------------------------------------------------------------------
$script:NodeFieldCs = @'
using System;
using System.Collections.Generic;
using System.Windows;
using System.Windows.Media;

public class NodeField : FrameworkElement
{
    class Node { public double X, Y, VX, VY, R, Ph; }
    List<Node> nodes = new List<Node>();
    Random rnd = new Random();
    Pen[] pens = new Pen[10];
    Brush glow; Brush core;
    public int Count = 70;
    public double LinkDist = 175;
    bool hooked = false;
    double w = 0, h = 0;
    DateTime last = DateTime.Now;

    public NodeField()
    {
        IsHitTestVisible = false;
        SetColors(Color.FromRgb(191, 227, 255), Color.FromRgb(92, 168, 255));
        Loaded   += (s, e) => { if (!hooked) { CompositionTarget.Rendering += Tick; hooked = true; } };
        Unloaded += (s, e) => { if (hooked)  { CompositionTarget.Rendering -= Tick; hooked = false; } };
    }

    public void SetColors(Color n, Color l)
    {
        for (int i = 0; i < pens.Length; i++)
        {
            byte a = (byte)(255.0 * (i + 1) / pens.Length * 0.55);
            Pen p = new Pen(new SolidColorBrush(Color.FromArgb(a, l.R, l.G, l.B)), 1.0);
            p.Freeze(); pens[i] = p;
        }
        RadialGradientBrush g = new RadialGradientBrush();
        g.GradientStops.Add(new GradientStop(Color.FromArgb(150, n.R, n.G, n.B), 0.0));
        g.GradientStops.Add(new GradientStop(Color.FromArgb(40, n.R, n.G, n.B), 0.45));
        g.GradientStops.Add(new GradientStop(Color.FromArgb(0, n.R, n.G, n.B), 1.0));
        g.Freeze(); glow = g;
        SolidColorBrush c = new SolidColorBrush(Color.FromArgb(255, n.R, n.G, n.B));
        c.Freeze(); core = c;
    }

    void Init()
    {
        nodes.Clear();
        for (int i = 0; i < Count; i++)
        {
            Node n = new Node();
            n.X = rnd.NextDouble() * w; n.Y = rnd.NextDouble() * h;
            n.VX = (rnd.NextDouble() - 0.5) * 36; n.VY = (rnd.NextDouble() - 0.5) * 36;
            n.R = 1.2 + rnd.NextDouble() * 2.0; n.Ph = rnd.NextDouble() * 6.28;
            nodes.Add(n);
        }
    }

    void Tick(object s, EventArgs e)
    {
        if (!IsVisible || ActualWidth < 10) return;
        double W = ActualWidth, H = ActualHeight;
        if (nodes.Count == 0 || Math.Abs(W - w) > 1 || Math.Abs(H - h) > 1) { w = W; h = H; Init(); }
        DateTime now = DateTime.Now;
        double dt = (now - last).TotalSeconds; last = now;
        if (dt > 0.1) dt = 0.1;
        foreach (Node n in nodes)
        {
            n.X += n.VX * dt; n.Y += n.VY * dt; n.Ph += dt;
            if (n.X < 0) { n.X = 0; n.VX = Math.Abs(n.VX); }
            if (n.X > W) { n.X = W; n.VX = -Math.Abs(n.VX); }
            if (n.Y < 0) { n.Y = 0; n.VY = Math.Abs(n.VY); }
            if (n.Y > H) { n.Y = H; n.VY = -Math.Abs(n.VY); }
        }
        InvalidateVisual();
    }

    protected override void OnRender(DrawingContext dc)
    {
        int c = nodes.Count;
        double L2 = LinkDist * LinkDist;
        for (int i = 0; i < c; i++)
        {
            Node a = nodes[i];
            for (int j = i + 1; j < c; j++)
            {
                Node b = nodes[j];
                double dx = a.X - b.X, dy = a.Y - b.Y, d2 = dx * dx + dy * dy;
                if (d2 < L2)
                {
                    int idx = (int)((1.0 - Math.Sqrt(d2) / LinkDist) * pens.Length);
                    if (idx >= pens.Length) idx = pens.Length - 1;
                    if (idx < 0) idx = 0;
                    dc.DrawLine(pens[idx], new Point(a.X, a.Y), new Point(b.X, b.Y));
                }
            }
        }
        foreach (Node n in nodes)
        {
            double pulse = 0.8 + 0.2 * Math.Sin(n.Ph * 2.0);
            double gr = n.R * 6.0 * pulse;
            Point p = new Point(n.X, n.Y);
            dc.DrawEllipse(glow, null, p, gr, gr);
            dc.DrawEllipse(core, null, p, n.R, n.R);
        }
    }
}
'@

