                    <Image x:Name="LogoHero" Grid.Column="1" Width="230" Height="230" RenderOptions.BitmapScalingMode="HighQuality" HorizontalAlignment="Center" VerticalAlignment="Center">
                      <Image.Effect><DropShadowEffect Color="#2F7BFF" BlurRadius="46" ShadowDepth="0" Opacity="0.6"/></Image.Effect>
                    </Image>
                  </Grid>
                </Border>

                <UniformGrid Grid.Row="1" Columns="5" Margin="0,0,0,16">
                  <Border Style="{StaticResource Card}" Margin="16,0,0,0" Height="104">
                    <StackPanel Margin="20,16" VerticalAlignment="Center">
                      <TextBlock Text="NIVEL DE RIESGO" FontSize="10.5" FontWeight="SemiBold" Foreground="{DynamicResource MutedBrush}"/>
                      <TextBlock x:Name="StRisk" Text="--" FontSize="28" FontWeight="SemiBold" Margin="0,4,0,0"/>
                      <TextBlock x:Name="StRiskSub" Text="sin escanear" FontSize="11" Foreground="{DynamicResource MutedBrush}"/>
                    </StackPanel>
                  </Border>
                  <Border Style="{StaticResource Card}" Margin="12,0,0,0" Height="104">
                    <StackPanel Margin="20,16" VerticalAlignment="Center">
                      <TextBlock Text="PROCESOS DESDE REINICIO" FontSize="10.5" FontWeight="SemiBold" Foreground="{DynamicResource MutedBrush}"/>
                      <TextBlock x:Name="StProc" Text="0" FontSize="28" FontWeight="SemiBold" Margin="0,4,0,0"/>
                      <TextBlock Text="analizados" FontSize="11" Foreground="{DynamicResource MutedBrush}"/>
                    </StackPanel>
                  </Border>
                  <Border Style="{StaticResource Card}" Margin="12,0,0,0" Height="104">
                    <StackPanel Margin="20,16" VerticalAlignment="Center">
                      <TextBlock Text="EJECUTADOS (BAM/PREFETCH)" FontSize="10.5" FontWeight="SemiBold" Foreground="{DynamicResource MutedBrush}"/>
                      <TextBlock x:Name="StExec" Text="0" FontSize="28" FontWeight="SemiBold" Margin="0,4,0,0"/>
                      <TextBlock Text="programas" FontSize="11" Foreground="{DynamicResource MutedBrush}"/>
                    </StackPanel>
                  </Border>
                  <Border Style="{StaticResource Card}" Margin="12,0,0,0" Height="104">
                    <StackPanel Margin="20,16" VerticalAlignment="Center">
                      <TextBlock Text="HALLAZGOS CRÍTICOS" FontSize="10.5" FontWeight="SemiBold" Foreground="{DynamicResource MutedBrush}"/>
                      <TextBlock x:Name="StCrit" Text="0" FontSize="28" FontWeight="SemiBold" Foreground="#FF4D6A" Margin="0,4,0,0"/>
                      <TextBlock Text="requieren revisión" FontSize="11" Foreground="{DynamicResource MutedBrush}"/>
                    </StackPanel>
                  </Border>
                  <Border Style="{StaticResource Card}" Margin="12,0,0,0" Height="104">
                    <StackPanel Margin="20,16" VerticalAlignment="Center">
                      <TextBlock Text="HALLAZGOS TOTALES" FontSize="10.5" FontWeight="SemiBold" Foreground="{DynamicResource MutedBrush}"/>
                      <TextBlock x:Name="StTotal" Text="0" FontSize="28" FontWeight="SemiBold" Margin="0,4,0,0"/>
                      <TextBlock Text="entre todas las categorías" FontSize="11" Foreground="{DynamicResource MutedBrush}"/>
                    </StackPanel>
                  </Border>
                </UniformGrid>

                <Grid Grid.Row="2">
                  <Grid.ColumnDefinitions>
                    <ColumnDefinition Width="1.45*"/>
                    <ColumnDefinition Width="*"/>
                  </Grid.ColumnDefinitions>
                  <Border Grid.Column="0" Style="{StaticResource Card}" Margin="16,0,0,0">
                    <Grid Margin="24,20,18,18">
                      <Grid.RowDefinitions>
                        <RowDefinition Height="Auto"/>
                        <RowDefinition Height="*"/>
                      </Grid.RowDefinitions>
                      <TextBlock Text="Registro en vivo" FontSize="15" FontWeight="SemiBold" Margin="0,0,0,10"/>
                      <TextBox x:Name="LogBox" Grid.Row="1" IsReadOnly="True" Background="Transparent" BorderThickness="0" FontFamily="Consolas" FontSize="12"
                               Foreground="{DynamicResource MutedBrush}" TextWrapping="Wrap" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled"/>
                    </Grid>
                  </Border>
                  <Border Grid.Column="1" Style="{StaticResource Card}" Margin="12,0,0,0">
                    <Grid Margin="24,20,24,18">
                      <Grid.RowDefinitions>
                        <RowDefinition Height="Auto"/>
                        <RowDefinition Height="*"/>
                      </Grid.RowDefinitions>
                      <TextBlock Text="Hallazgos por categoría" FontSize="15" FontWeight="SemiBold" Margin="0,0,0,12"/>
                      <ScrollViewer Grid.Row="1" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
                        <StackPanel x:Name="CatBars"/>
                      </ScrollViewer>
                    </Grid>
                  </Border>
                </Grid>
              </Grid>

              <!-- ===== PAGE: HALLAZGOS ===== -->
              <Grid x:Name="PageFind" Visibility="Collapsed">
                <Grid.RowDefinitions>
                  <RowDefinition Height="Auto"/>
                  <RowDefinition Height="*"/>
                </Grid.RowDefinitions>
                <StackPanel Orientation="Horizontal" Margin="16,4,0,14">
                  <RadioButton x:Name="FAll"  Style="{StaticResource Pill}" GroupName="F" Content="Todos" IsChecked="True"/>
                  <RadioButton x:Name="FHigh" Style="{StaticResource Pill}" GroupName="F" Content="Críticos"/>
                  <RadioButton x:Name="FMed"  Style="{StaticResource Pill}" GroupName="F" Content="Medios"/>
                  <RadioButton x:Name="FInfo" Style="{StaticResource Pill}" GroupName="F" Content="Info"/>
                </StackPanel>
                <Border Grid.Row="1" Style="{StaticResource Card}" Margin="16,0,0,0">
                  <Grid>
                    <ScrollViewer VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled" Margin="0,0,6,0">
                      <StackPanel x:Name="FindList" Margin="20,18,14,12"/>
                    </ScrollViewer>
                    <TextBlock x:Name="EmptyMsg" Text="Todavía no hay hallazgos. Ejecutá un escaneo desde el Panel." HorizontalAlignment="Center" VerticalAlignment="Center" Foreground="{DynamicResource MutedBrush}"/>
                  </Grid>
                </Border>
              </Grid>

              <!-- ===== PAGE: RESUMEN ===== -->
              <Grid x:Name="PageSum" Visibility="Collapsed">
                <Grid.RowDefinitions>
                  <RowDefinition Height="Auto"/>
                  <RowDefinition Height="*"/>
                </Grid.RowDefinitions>
                <StackPanel Orientation="Horizontal" Margin="16,4,0,14">
                  <Button x:Name="BtnExport" Style="{StaticResource GradBtn}" Content="Exportar reporte (.txt)" Padding="22,11"/>
                  <Button x:Name="BtnCopy" Style="{StaticResource GhostBtn}" Content="Copiar al portapapeles" Margin="12,0,0,0" Padding="20,11"/>
                  <TextBlock x:Name="ExportMsg" VerticalAlignment="Center" Margin="16,0,0,0" FontSize="12" Foreground="{DynamicResource Accent2Brush}"/>
                </StackPanel>
                <Border Grid.Row="1" Style="{StaticResource Card}" Margin="16,0,0,0">
                  <TextBox x:Name="SummaryBox" IsReadOnly="True" Background="Transparent" BorderThickness="0" Margin="24,20,16,18" FontFamily="Consolas" FontSize="13" Foreground="{DynamicResource TextBrush}"
                           TextWrapping="Wrap" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled"
                           Text="Ejecutá un escaneo para generar el resumen."/>
                </Border>
              </Grid>

              <!-- ===== PAGE: AJUSTES ===== -->
              <ScrollViewer x:Name="PageSet" Visibility="Collapsed" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
                <StackPanel Margin="16,0,0,0">
                  <Border Style="{StaticResource Card}" Padding="28,22" Margin="0,0,0,14">
                    <StackPanel>
                      <TextBlock Text="Apariencia" FontSize="16" FontWeight="SemiBold" Margin="0,0,0,14"/>
                      <Grid Margin="0,0,0,16">
                        <StackPanel>
                          <TextBlock Text="Modo oscuro (Dark Blue)" FontSize="14" FontWeight="SemiBold"/>
                          <TextBlock Text="Desactivalo para usar el tema claro." FontSize="12" Foreground="{DynamicResource MutedBrush}" Margin="0,2,0,0"/>
                        </StackPanel>
                        <CheckBox x:Name="ThemeToggle" Style="{StaticResource Switch}" IsChecked="True" HorizontalAlignment="Right" VerticalAlignment="Center"/>
                      </Grid>
                      <Grid>
                        <StackPanel>
                          <TextBlock Text="Partículas de fondo (nodos)" FontSize="14" FontWeight="SemiBold"/>
                          <TextBlock Text="Nodos con glow que se conectan entre sí." FontSize="12" Foreground="{DynamicResource MutedBrush}" Margin="0,2,0,0"/>
                        </StackPanel>
                        <CheckBox x:Name="PartToggle" Style="{StaticResource Switch}" IsChecked="True" HorizontalAlignment="Right" VerticalAlignment="Center"/>
                      </Grid>
                    </StackPanel>
                  </Border>
                  <Border Style="{StaticResource Card}" Padding="28,22" Margin="0,0,0,14">
                    <StackPanel>
                      <TextBlock Text="Módulos de escaneo" FontSize="16" FontWeight="SemiBold" Margin="0,0,0,14"/>
                      <Grid Margin="0,0,0,16">
                        <StackPanel>
                          <TextBlock Text="Navegadores (historial, cookies, credenciales guardadas)" FontSize="14" FontWeight="SemiBold"/>
                          <TextBlock Text="Chrome, Edge, Brave, Opera / GX, Vivaldi y Firefox. Solo lee URLs y dominios, nunca contraseñas." FontSize="12" Foreground="{DynamicResource MutedBrush}" Margin="0,2,0,0"/>
                        </StackPanel>
                        <CheckBox x:Name="BrowserToggle" Style="{StaticResource Switch}" IsChecked="True" HorizontalAlignment="Right" VerticalAlignment="Center"/>
                      </Grid>
                      <Grid>
                        <StackPanel>
                          <TextBlock Text="Archivos recientes y descargas" FontSize="14" FontWeight="SemiBold"/>
                          <TextBlock Text="Descargas, Escritorio, Temp y accesos recientes creados desde el reinicio." FontSize="12" Foreground="{DynamicResource MutedBrush}" Margin="0,2,0,0"/>
                        </StackPanel>
                        <CheckBox x:Name="FilesToggle" Style="{StaticResource Switch}" IsChecked="True" HorizontalAlignment="Right" VerticalAlignment="Center"/>
                      </Grid>
                    </StackPanel>
                  </Border>
                  <Border Style="{StaticResource Card}" Padding="28,22">
                    <StackPanel>
                      <TextBlock Text="Sistema" FontSize="16" FontWeight="SemiBold" Margin="0,0,0,10"/>
                      <TextBlock x:Name="SysInfo" FontSize="12.5" Foreground="{DynamicResource MutedBrush}" TextWrapping="Wrap" LineHeight="20"/>
                    </StackPanel>
                  </Border>
                </StackPanel>
              </ScrollViewer>

            </Grid>
          </Grid>
        </Grid>
      </Grid>
    </Border>
  </Grid>
</Window>
'@

# --------------------------------------------------------------------------
#  MOTOR DE ESCANEO (corre en un runspace aparte para no congelar la UI)
# --------------------------------------------------------------------------
$script:ScanScript = @'
$ErrorActionPreference = 'SilentlyContinue'
$cfg  = $S.Cfg
$ro   = [System.Text.RegularExpressions.RegexOptions]::IgnoreCase
$High = [regex]::new($cfg.High, $ro)
$Med  = [regex]::new($cfg.Med, $ro)
$Dom  = [regex]::new($cfg.Domains, $ro)
$seen = New-Object 'System.Collections.Generic.HashSet[string]'

function Log($m)  { [void]$S.Log.Add(('[{0}] {1}' -f (Get-Date -Format 'HH:mm:ss'), $m)) }
function Step($p, $m) { $S.Progress = $p; $S.Status = $m; Log $m }
function Add-Find($sev, $cat, $title, $detail) {
    $k = "$cat|$title"
    if ($seen.Add($k)) { [void]$S.Findings.Add([pscustomobject]@{ Sev = $sev; Cat = $cat; Title = $title; Detail = $detail }) }
}
function Check($text, $strict, $cat, $title, $detail) {
    if ($High.IsMatch($text)) { Add-Find 'HIGH' $cat $title $detail; return 'HIGH' }
    if (-not $strict -and $Med.IsMatch($text)) { Add-Find 'MED' $cat $title $detail; return 'MED' }
    return $null
}
function Trunc($s, $n) { if ($s.Length -gt $n) { return $s.Substring(0, $n) + '...' } else { return $s } }
function Read-Raw($path, $maxMB) {
    try {
        $fs = [System.IO.File]::Open($path, 'Open', 'Read', 'ReadWrite,Delete')
        try {
            $len = [int][math]::Min($fs.Length, $maxMB * 1MB)
            $buf = New-Object byte[] $len
            $off = 0
            while ($off -lt $len) { $r = $fs.Read($buf, $off, $len - $off); if ($r -le 0) { break }; $off += $r }
            return [Text.Encoding]::GetEncoding(28591).GetString($buf, 0, $off)
        } finally { $fs.Dispose() }
    } catch { return $null }
}

try {
    # ---------------- 1. REINICIO ----------------
    Step 3 'Leyendo hora del ultimo reinicio'
    $boot = (Get-CimInstance Win32_OperatingSystem).LastBootUpTime
    $S.Boot = $boot
    Log ('Ultimo reinicio: {0}' -f $boot)

    # ---------------- 2. PROCESOS ----------------
    Step 8 'Analizando procesos iniciados desde el reinicio'
    $n = 0; $tmpCount = 0
    foreach ($p in (Get-CimInstance Win32_Process)) {
        if ($p.CreationDate -and $p.CreationDate -lt $boot.AddMinutes(-1)) { continue }
        $n++
        $name = [string]$p.Name; $path = [string]$p.ExecutablePath; $cmd = [string]$p.CommandLine
        $t = if ($p.CreationDate) { $p.CreationDate.ToString('HH:mm:ss') } else { '--:--:--' }
        [void]$S.ProcList.Add(('{0} | {1} | {2}' -f $t, $name, $path))
        $r = Check ("$name $path") $false 'Procesos' ("Proceso sospechoso: $name") ("Ruta: $path")
        if (-not $r) { $r = Check $cmd $true 'Procesos' ("Linea de comando sospechosa: $name") (Trunc $cmd 160) }
        if (-not $r -and $path -match '\\(Temp|Downloads|Desktop)\\' -and $tmpCount -lt 20) {
            $tmpCount++
            Add-Find 'INFO' 'Procesos' ("Ejecutandose desde carpeta de usuario: $name") ("Ruta: $path")
        }
    }
    $S.Counts.Proc = $n
    Log ("Procesos analizados: $n")
    foreach ($pr in (Get-Process | Where-Object { $_.MainWindowTitle })) {
        Check $pr.MainWindowTitle $false 'Procesos' ("Ventana abierta: " + (Trunc $pr.MainWindowTitle 70)) ("Proceso: " + $pr.ProcessName) | Out-Null
    }

    # ---------------- 3. BAM (programas ejecutados) ----------------
    Step 22 'Leyendo historial de ejecucion (BAM)'
    $bam = 'HKLM:\SYSTEM\CurrentControlSet\Services\bam\State\UserSettings'
    $exCount = 0
    if (Test-Path $bam) {
        foreach ($sid in (Get-ChildItem $bam)) {
            foreach ($vn in $sid.GetValueNames()) {
                if ($vn -notmatch '\\') { continue }
                $b = $sid.GetValue($vn)
                if ($b -is [byte[]] -and $b.Length -ge 8) {
                    $dt = [DateTime]::FromFileTimeUtc([BitConverter]::ToInt64($b, 0)).ToLocalTime()
                    if ($dt -ge $boot) {
                        $exCount++
                        [void]$S.Exec.Add(@{ Time = $dt; Src = 'BAM'; Path = $vn })
                        Check $vn $false 'Ejecucion' ("Programa ejecutado: " + (Split-Path $vn -Leaf)) ("{0}  -  {1}" -f $dt.ToString('HH:mm:ss'), $vn) | Out-Null
                    }
                }
            }
        }
    } else { Log 'BAM no disponible (ejecuta como Administrador para ver mas).' }

    # ---------------- 4. PREFETCH ----------------
    Step 28 'Revisando Prefetch'
    $pf = Get-ChildItem 'C:\Windows\Prefetch\*.pf' | Where-Object { $_.LastWriteTime -ge $boot }
    foreach ($f in $pf) {
        $exCount++
        [void]$S.Exec.Add(@{ Time = $f.LastWriteTime; Src = 'Prefetch'; Path = ($f.Name -replace '\.pf$', '') })
        Check $f.Name $false 'Ejecucion' ("Prefetch: " + $f.Name) ("Ultima ejecucion: " + $f.LastWriteTime.ToString('HH:mm:ss')) | Out-Null
    }
    if (-not $S.Admin) { Log 'Prefetch requiere Administrador para listar.' }
    $S.Counts.Exec = $exCount

    # ---------------- 5. ARCHIVOS ----------------
    if ($S.OptFiles) {
        Step 36 'Buscando archivos nuevos (Descargas, Escritorio, Temp, Recientes)'
        $dirs = @("$env:USERPROFILE\Downloads", "$env:USERPROFILE\Desktop", $env:TEMP)
        $newCount = 0; $exeShown = 0
        foreach ($d in $dirs) {
            if (-not (Test-Path $d)) { continue }
            $files = Get-ChildItem $d -File -Recurse -Depth 2 | Where-Object { $_.CreationTime -ge $boot -or $_.LastWriteTime -ge $boot } | Select-Object -First 2500
            foreach ($f in $files) {
                $newCount++
                $r = Check $f.Name $false 'Archivos' ("Archivo: " + $f.Name) $f.FullName
                if (-not $r -and $f.Extension -match '^\.(exe|dll|sys|bat|cmd|ps1|vbs|jar|asi)$' -and $exeShown -lt 25 -and $d -notmatch 'Temp') {
                    $exeShown++
                    Add-Find 'INFO' 'Archivos' ("Ejecutable nuevo: " + $f.Name) $f.FullName
                }
            }
        }
        $rec = Get-ChildItem "$env:APPDATA\Microsoft\Windows\Recent\*.lnk" | Where-Object { $_.LastWriteTime -ge $boot }
        foreach ($l in $rec) { $newCount++; Check $l.BaseName $false 'Archivos' ("Reciente: " + $l.BaseName) ("Acceso: " + $l.LastWriteTime.ToString('HH:mm:ss')) | Out-Null }
        $S.Counts.Files = $newCount
        Log ("Archivos nuevos/recientes: $newCount")
    }

    # ---------------- 6. EVENTOS DEL SISTEMA ----------------
    Step 46 'Revisando registros de eventos'
    $svc = Get-WinEvent -FilterHashtable @{ LogName = 'System'; Id = 7045; StartTime = $boot } -MaxEvents 80
    foreach ($e in $svc) {
        $sn = [string]$e.Properties[0].Value; $ip = [string]$e.Properties[1].Value
        $r = Check "$sn $ip" $false 'Sistema' ("Servicio/driver instalado: $sn") ("{0}  -  {1}" -f $e.TimeCreated.ToString('HH:mm:ss'), $ip)
        if (-not $r) {
            if ($ip -match '\.sys' -and $ip -notmatch 'system32') { Add-Find 'MED' 'Sistema' ("Driver fuera de System32: $sn") $ip }
            else { Add-Find 'INFO' 'Sistema' ("Servicio instalado desde el reinicio: $sn") $ip }
        }
    }
    $clr1 = Get-WinEvent -FilterHashtable @{ LogName = 'System'; Id = 104; StartTime = (Get-Date).AddDays(-7) } -MaxEvents 3
    $clr2 = Get-WinEvent -FilterHashtable @{ LogName = 'Security'; Id = 1102; StartTime = (Get-Date).AddDays(-7) } -MaxEvents 3
    foreach ($e in @($clr1) + @($clr2)) { if ($e) { Add-Find 'HIGH' 'Sistema' 'Registros de eventos de Windows BORRADOS' ("Fecha: " + $e.TimeCreated + "  (posible borrado de rastros)") } }

    # ---------------- 7. DNS ----------------
    Step 52 'Revisando cache DNS'
    $dnsN = 0
    foreach ($d in (Get-DnsClientCache | Select-Object -ExpandProperty Entry -Unique)) {
        $dnsN++
        if ($Dom.IsMatch($d)) { Add-Find 'HIGH' 'Red' ("Dominio de cheats resuelto: $d") 'Presente en la cache DNS (acceso reciente a ese sitio)' }
        elseif ($High.IsMatch($d)) { Add-Find 'HIGH' 'Red' ("Dominio sospechoso en DNS: $d") 'Cache DNS' }
    }
    Log ("Entradas DNS revisadas: $dnsN")

    # ---------------- 8. NAVEGADORES ----------------
    if ($S.OptBrowser) {
        Step 58 'Buscando navegadores instalados'
        $urlPat  = [regex]::new("https?://[A-Za-z0-9\-._~:/?#\[\]@!`$&'()*+,;=%]{4,400}")
        $hostPat = [regex]::new('[A-Za-z0-9][A-Za-z0-9\-\.]{2,60}\.(com|net|org|cc|gg|io|xyz|to|me|ru|app|dev|shop|store|ws|pro|club|top|info|tv|es|ar)\b', $ro)
        $mailPat = [regex]::new('"email"\s*:\s*"([^"]+@[^"]+)"')

        $chromium = @(
            @{ N = 'Google Chrome'; P = "$env:LOCALAPPDATA\Google\Chrome\User Data" },
            @{ N = 'Microsoft Edge'; P = "$env:LOCALAPPDATA\Microsoft\Edge\User Data" },
            @{ N = 'Brave'; P = "$env:LOCALAPPDATA\BraveSoftware\Brave-Browser\User Data" },
            @{ N = 'Vivaldi'; P = "$env:LOCALAPPDATA\Vivaldi\User Data" },
            @{ N = 'Opera'; P = "$env:APPDATA\Opera Software\Opera Stable"; Flat = $true },
            @{ N = 'Opera GX'; P = "$env:APPDATA\Opera Software\Opera GX Stable"; Flat = $true }
        )
        $profiles = @()
        foreach ($c in $chromium) {
            if (-not (Test-Path $c.P)) { continue }
            [void]$S.Browsers.Add($c.N)
            if ($c.Flat) { $profiles += @{ N = $c.N; P = $c.P } }
            else { foreach ($d in (Get-ChildItem $c.P -Directory | Where-Object { $_.Name -eq 'Default' -or $_.Name -like 'Profile *' })) { $profiles += @{ N = ($c.N + ' / ' + $d.Name); P = $d.FullName } } }
        }
        $ffRoot = "$env:APPDATA\Mozilla\Firefox\Profiles"
        if (Test-Path $ffRoot) { [void]$S.Browsers.Add('Firefox'); foreach ($d in (Get-ChildItem $ffRoot -Directory)) { $profiles += @{ N = ('Firefox / ' + $d.Name); P = $d.FullName; FF = $true } } }
        Log ('Navegadores detectados: ' + ($S.Browsers -join ', '))

        $pi = 0
        foreach ($pf in $profiles) {
            $pi++
            Step ([int](58 + 28 * $pi / [math]::Max(1, $profiles.Count))) ("Analizando " + $pf.N)
            if ($pf.FF) { $hist = @('places.sqlite', 'places.sqlite-wal'); $cook = @('cookies.sqlite', 'cookies.sqlite-wal'); $logn = @('logins.json') }
            else { $hist = @('History', 'History-wal'); $cook = @('Network\Cookies', 'Cookies', 'Network\Cookies-wal'); $logn = @('Login Data', 'Login Data-wal', 'Login Data For Account') }

            # --- historial / busquedas ---
            $cnt = 0; $locked = $false
            foreach ($h in $hist) {
                $fp = Join-Path $pf.P $h
                if (-not (Test-Path $fp)) { continue }
                $raw = Read-Raw $fp 150
                if ($null -eq $raw) { $locked = $true; continue }
                $urls = New-Object 'System.Collections.Generic.HashSet[string]'
                foreach ($m in $urlPat.Matches($raw)) { [void]$urls.Add($m.Value) }
                foreach ($u in $urls) {
                    if ($cnt -ge 40) { break }
                    try { $dec = [uri]::UnescapeDataString(($u -replace '\+', ' ')) } catch { $dec = $u }
                    $sev = $null
                    if ($High.IsMatch($dec) -or $Dom.IsMatch(($u -replace '^https?://([^/]+).*$', '$1'))) { $sev = 'HIGH' } elseif ($Med.IsMatch($dec)) { $sev = 'MED' }
                    if ($sev) {
                        $cnt++
                        $kind = if ($dec -match '[?&](q|query|search_query|text|p)=') { 'Busqueda' } else { 'Visita' }
                        Add-Find $sev 'Navegador' ("$kind en " + $pf.N + ": " + (Trunc $dec 95)) 'Historial del navegador'
                    }
                }
                $raw = $null
            }
            if ($locked) { Log ($pf.N + ': historial bloqueado (cerra el navegador para analizarlo).') }

            # --- cookies / sesiones ---
            foreach ($h in $cook) {
                $fp = Join-Path $pf.P $h
                if (-not (Test-Path $fp)) { continue }
                $raw = Read-Raw $fp 80
                if ($null -eq $raw) { continue }
                $hosts = New-Object 'System.Collections.Generic.HashSet[string]'
                foreach ($m in $hostPat.Matches($raw)) { if ($Dom.IsMatch($m.Value)) { [void]$hosts.Add($m.Value.ToLower()) } }
                foreach ($hn in $hosts) { Add-Find 'HIGH' 'Sesiones' ("Cookies/sesion de sitio de cheats: $hn") ("Navegador: " + $pf.N + " (posible cuenta logueada)") }
                $raw = $null
            }

            # --- credenciales guardadas (solo dominios) ---
            foreach ($h in $logn) {
                $fp = Join-Path $pf.P $h
                if (-not (Test-Path $fp)) { continue }
                $raw = Read-Raw $fp 20
                if ($null -eq $raw) { continue }
                $hosts = New-Object 'System.Collections.Generic.HashSet[string]'
                foreach ($m in $urlPat.Matches($raw)) { $hh = ($m.Value -replace '^https?://([^/:?#]+).*$', '$1'); if ($Dom.IsMatch($hh)) { [void]$hosts.Add($hh.ToLower()) } }
                foreach ($hn in $hosts) { Add-Find 'HIGH' 'Sesiones' ("Credenciales guardadas para sitio de cheats: $hn") ("Navegador: " + $pf.N) }
                $raw = $null
            }

            # --- cuentas / correos logueados en el navegador ---
            if (-not $pf.FF) {
                $fp = Join-Path $pf.P 'Preferences'
                if (Test-Path $fp) {
                    $raw = Read-Raw $fp 5
                    if ($raw) { foreach ($m in $mailPat.Matches($raw)) { $mail = $m.Groups[1].Value; if (-not $S.Accounts.Contains($mail)) { [void]$S.Accounts.Add($mail) } } }
                    $raw = $null
                }
            }
        }
        foreach ($a in $S.Accounts) { Add-Find 'INFO' 'Sesiones' ("Cuenta logueada en el navegador: $a") 'Revisa si esta cuenta aparece en paginas de cheats' }
    }

    # ---------------- 9. PROGRAMAS INSTALADOS / INICIO ----------------
    Step 88 'Revisando programas instalados y arranque'
    $unKeys = @('HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*', 'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*', 'HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*')
    foreach ($k in $unKeys) { foreach ($it in (Get-ItemProperty $k)) { if ($it.DisplayName) { Check $it.DisplayName $false 'Sistema' ("Programa instalado: " + $it.DisplayName) ("Fecha de instalacion: " + $it.InstallDate) | Out-Null } } }
    foreach ($rk in @('HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run', 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run')) {
        $props = Get-ItemProperty $rk
        if ($props) { foreach ($pp in $props.PSObject.Properties) { if ($pp.Name -notmatch '^PS') { Check ("$($pp.Name) $($pp.Value)") $false 'Sistema' ("Inicio automatico: " + $pp.Name) ([string]$pp.Value) | Out-Null } } }
    }

    # ---------------- 10. FIVEM ----------------
    Step 94 'Revisando carpetas de FiveM'
    $fv = "$env:LOCALAPPDATA\FiveM\FiveM.app"
    if (Test-Path $fv) {
        $S.FiveM = $true
        foreach ($f in (Get-ChildItem "$fv\plugins" -File)) { Add-Find 'MED' 'FiveM' ("Plugin cargado en FiveM: " + $f.Name) $f.FullName }
        foreach ($f in (Get-ChildItem $fv -File -Filter *.asi)) { Add-Find 'MED' 'FiveM' ("Archivo .asi en FiveM.app: " + $f.Name) $f.FullName }
        foreach ($f in (Get-ChildItem "$fv\mods" -File -Recurse | Select-Object -First 30)) { Add-Find 'INFO' 'FiveM' ("Archivo en mods: " + $f.Name) $f.FullName }
    }

    Step 100 'Escaneo completado'
} catch {
    Log ('ERROR: ' + $_.Exception.Message)
} finally {
    $S.Done = $true
}
'@

# --------------------------------------------------------------------------
#  UI: helpers
# --------------------------------------------------------------------------
function Get-Color([string]$h) { [System.Windows.Media.ColorConverter]::ConvertFromString($h) }
function New-Brush([string]$h) { New-Object System.Windows.Media.SolidColorBrush -ArgumentList (Get-Color $h) }
function New-Grad($stops, $x1, $y1, $x2, $y2) {
    $g = New-Object System.Windows.Media.LinearGradientBrush
    $g.StartPoint = [System.Windows.Point]::new($x1, $y1)
    $g.EndPoint   = [System.Windows.Point]::new($x2, $y2)
    foreach ($s in $stops) { $g.GradientStops.Add([System.Windows.Media.GradientStop]::new([System.Windows.Media.Color](Get-Color $s[0]), [double]$s[1])) }
    return $g
}

function Set-Theme([bool]$dark) {
    $r = $script:win.Resources
    if ($dark) {
        $pal = @{
            CardBrush = '#B30A1224'; CardBorderBrush = '#3A4A8CFF'; TextBrush = '#EAF2FF'; MutedBrush = '#8D9DBA'
            AccentBrush = '#2F7BFF'; Accent2Brush = '#4FC3FF'; NavActiveBrush = '#2E2F7BFF'; HoverBrush = '#1AFFFFFF'
            TrackBrush = '#33FFFFFF'; ThumbBrush = '#664A8CFF'; RowBrush = '#660B1730'; ShellBorderBrush = '#3A4A8CFF'
        }
        $r['BgGrad']     = New-Grad @(@('#03060C', 0), @('#0A1A3C', 0.55), @('#030710', 1)) 0 0 1 1
        $r['AccentGrad'] = New-Grad @(@('#2F6BFF', 0), @('#3FD0FF', 1)) 0 0 1 0
        $script:field.SetColors((Get-Color '#BFE3FF'), (Get-Color '#5CA8FF'))
    } else {
        $pal = @{
            CardBrush = '#D9FFFFFF'; CardBorderBrush = '#331F63E6'; TextBrush = '#0B1630'; MutedBrush = '#5A6B8C'
            AccentBrush = '#1F63E6'; Accent2Brush = '#1479D6'; NavActiveBrush = '#1F1F63E6'; HoverBrush = '#12000000'
            TrackBrush = '#2A000000'; ThumbBrush = '#551F63E6'; RowBrush = '#99FFFFFF'; ShellBorderBrush = '#331F63E6'
        }
        $r['BgGrad']     = New-Grad @(@('#F6F9FF', 0), @('#DCE8FF', 0.55), @('#EEF4FF', 1)) 0 0 1 1
        $r['AccentGrad'] = New-Grad @(@('#1F63E6', 0), @('#27B3F5', 1)) 0 0 1 0
        $script:field.SetColors((Get-Color '#2F7BFF'), (Get-Color '#2F7BFF'))
    }
    foreach ($k in $pal.Keys) { $r[$k] = New-Brush $pal[$k] }
}

function Show-Page([string]$name) {
    $titles = @{ Dash = 'Panel de control'; Find = 'Hallazgos'; Sum = 'Resumen del escaneo'; Set = 'Ajustes' }
    foreach ($p in 'Dash', 'Find', 'Sum', 'Set') {
        $script:ui["Page$p"].Visibility = if ($p -eq $name) { 'Visible' } else { 'Collapsed' }
    }
    $script:ui.PageTitle.Text = $titles[$name]
    $anim = New-Object System.Windows.Media.Animation.DoubleAnimation -ArgumentList 0.0, 1.0, ([TimeSpan]::FromMilliseconds(300))
    $script:ui["Page$name"].BeginAnimation([System.Windows.UIElement]::OpacityProperty, $anim)
}

function Get-Risk($arr) {
    $hi = @($arr | Where-Object { $_.Sev -eq 'HIGH' }).Count
    $md = @($arr | Where-Object { $_.Sev -eq 'MED' }).Count
    $score = [math]::Min(100, $hi * 30 + $md * 8)
    if ($hi -eq 0 -and $md -eq 0) { $l = 'LIMPIO'; $c = '#35E0A1' }
    elseif ($score -lt 30) { $l = 'BAJO'; $c = '#4FC3FF' }
    elseif ($score -lt 70) { $l = 'MEDIO'; $c = '#FFB84D' }
    else { $l = 'ALTO'; $c = '#FF4D6A' }
    return @{ Score = $score; Label = $l; Color = $c; High = $hi; Med = $md }
}

function New-FindRow($f) {
    $map = @{ HIGH = @('#FF4D6A', 'CRÍTICO'); MED = @('#FFB84D', 'MEDIO'); INFO = @('#4FC3FF', 'INFO') }[$f.Sev]
    $col = Get-Color $map[0]
    $row = New-Object System.Windows.Controls.Border
    $row.CornerRadius = [System.Windows.CornerRadius]::new(12)
    $row.Padding = [System.Windows.Thickness]::new(14, 12, 14, 12)
    $row.Margin  = [System.Windows.Thickness]::new(0, 0, 0, 8)
    $row.SetResourceReference([System.Windows.Controls.Border]::BackgroundProperty, 'RowBrush')
    $g = New-Object System.Windows.Controls.Grid
    foreach ($w in 96, 120, 0) {
        $cd = New-Object System.Windows.Controls.ColumnDefinition
        if ($w -eq 0) { $cd.Width = [System.Windows.GridLength]::new(1, 'Star') } else { $cd.Width = [System.Windows.GridLength]::new($w) }
        $g.ColumnDefinitions.Add($cd)
    }
    $chip = New-Object System.Windows.Controls.Border
    $chip.CornerRadius = [System.Windows.CornerRadius]::new(8)
    $chip.Padding = [System.Windows.Thickness]::new(9, 3, 9, 3)
    $chip.HorizontalAlignment = 'Left'; $chip.VerticalAlignment = 'Top'
    $chip.Background = New-Object System.Windows.Media.SolidColorBrush -ArgumentList ([System.Windows.Media.Color]::FromArgb(0x33, $col.R, $col.G, $col.B))
    $ct = New-Object System.Windows.Controls.TextBlock
    $ct.Text = $map[1]; $ct.FontSize = 10.5; $ct.FontWeight = 'Bold'; $ct.Foreground = New-Object System.Windows.Media.SolidColorBrush -ArgumentList $col
    $chip.Child = $ct
    $cat = New-Object System.Windows.Controls.TextBlock
    $cat.Text = $f.Cat; $cat.FontSize = 12; $cat.Margin = [System.Windows.Thickness]::new(0, 3, 0, 0)
    $cat.SetResourceReference([System.Windows.Controls.TextBlock]::ForegroundProperty, 'MutedBrush')
    [System.Windows.Controls.Grid]::SetColumn($cat, 1)
    $sp = New-Object System.Windows.Controls.StackPanel
    [System.Windows.Controls.Grid]::SetColumn($sp, 2)
    $tt = New-Object System.Windows.Controls.TextBlock
    $tt.Text = $f.Title; $tt.FontSize = 13.5; $tt.FontWeight = 'SemiBold'; $tt.TextWrapping = 'Wrap'
    $dd = New-Object System.Windows.Controls.TextBlock
    $dd.Text = $f.Detail; $dd.FontSize = 11.5; $dd.TextWrapping = 'Wrap'; $dd.Margin = [System.Windows.Thickness]::new(0, 3, 0, 0)
    $dd.SetResourceReference([System.Windows.Controls.TextBlock]::ForegroundProperty, 'MutedBrush')
    [void]$sp.Children.Add($tt); [void]$sp.Children.Add($dd)
    [void]$g.Children.Add($chip); [void]$g.Children.Add($cat); [void]$g.Children.Add($sp)
    $row.Child = $g
    return $row
}

function Update-Findings {
    $ui = $script:ui
    $ui.FindList.Children.Clear()
    $arr = @()
    if ($script:S) { $arr = $script:S.Findings.ToArray() }
    $order = @{ HIGH = 0; MED = 1; INFO = 2 }
    $arr = $arr | Sort-Object { $order[$_.Sev] }
    if ($script:filter -ne 'ALL') { $arr = $arr | Where-Object { $_.Sev -eq $script:filter } }
    $shown = 0
    foreach ($f in $arr) { if ($shown -ge 500) { break }; [void]$ui.FindList.Children.Add((New-FindRow $f)); $shown++ }
    $ui.EmptyMsg.Visibility = if ($shown -eq 0) { 'Visible' } else { 'Collapsed' }
    if ($script:S -and $script:S.Done -and $shown -eq 0) { $ui.EmptyMsg.Text = 'Sin hallazgos en esta categoría.' }
}

function Update-CatBars {
    $ui = $script:ui
    $ui.CatBars.Children.Clear()
    $arr = $script:S.Findings.ToArray()
    $cats = 'Procesos', 'Ejecucion', 'Navegador', 'Sesiones', 'Archivos', 'Sistema', 'Red', 'FiveM'
    $counts = @{}
    foreach ($c in $cats) { $counts[$c] = @($arr | Where-Object { $_.Cat -eq $c }).Count }
    $max = [math]::Max(1, ($counts.Values | Measure-Object -Maximum).Maximum)
    foreach ($c in $cats) {
        $n = $counts[$c]
        $wrap = New-Object System.Windows.Controls.StackPanel
        $wrap.Margin = [System.Windows.Thickness]::new(0, 0, 0, 13)
        $hd = New-Object System.Windows.Controls.Grid
        $lb = New-Object System.Windows.Controls.TextBlock; $lb.Text = $c; $lb.FontSize = 12.5
        $nb = New-Object System.Windows.Controls.TextBlock; $nb.Text = [string]$n; $nb.FontSize = 12.5; $nb.FontWeight = 'SemiBold'; $nb.HorizontalAlignment = 'Right'
        [void]$hd.Children.Add($lb); [void]$hd.Children.Add($nb)
        $bar = New-Object System.Windows.Controls.Grid
        $bar.Margin = [System.Windows.Thickness]::new(0, 5, 0, 0)
        $c1 = New-Object System.Windows.Controls.ColumnDefinition; $c2 = New-Object System.Windows.Controls.ColumnDefinition
        $ratio = [double]$n / $max
        $c1.Width = [System.Windows.GridLength]::new($ratio, 'Star'); $c2.Width = [System.Windows.GridLength]::new(1.0 - $ratio + 0.0001, 'Star')
        $bar.ColumnDefinitions.Add($c1); $bar.ColumnDefinitions.Add($c2)
        $trk = New-Object System.Windows.Controls.Border; $trk.Height = 7; $trk.CornerRadius = [System.Windows.CornerRadius]::new(4)
        $trk.SetResourceReference([System.Windows.Controls.Border]::BackgroundProperty, 'TrackBrush')
        [System.Windows.Controls.Grid]::SetColumnSpan($trk, 2)
        $fill = New-Object System.Windows.Controls.Border; $fill.Height = 7; $fill.CornerRadius = [System.Windows.CornerRadius]::new(4)
        $fill.SetResourceReference([System.Windows.Controls.Border]::BackgroundProperty, 'AccentGrad')
        [void]$bar.Children.Add($trk); [void]$bar.Children.Add($fill)
        [void]$wrap.Children.Add($hd); [void]$wrap.Children.Add($bar)
        [void]$ui.CatBars.Children.Add($wrap)
    }
}

function Build-Summary {
    $S = $script:S
    $arr = $S.Findings.ToArray()
    $risk = Get-Risk $arr
    $sb = New-Object System.Text.StringBuilder
    $line = ('=' * 78)
    [void]$sb.AppendLine($line)
    [void]$sb.AppendLine('  PXTDETECTED.IA  -  REPORTE DE ESCANEO')
    [void]$sb.AppendLine($line)
    [void]$sb.AppendLine(('Fecha del escaneo : {0}' -f (Get-Date -Format 'dd/MM/yyyy HH:mm:ss')))
    [void]$sb.AppendLine(('Equipo / Usuario  : {0} / {1}' -f $env:COMPUTERNAME, $env:USERNAME))
    if ($S.Boot) { [void]$sb.AppendLine(('Ultimo reinicio   : {0}  (hace {1:N1} h)' -f $S.Boot, ((Get-Date) - $S.Boot).TotalHours)) }
    [void]$sb.AppendLine(('Administrador     : {0}' -f $(if ($S.Admin) { 'Si' } else { 'No (resultados parciales)' })))
    [void]$sb.AppendLine(('Navegadores       : {0}' -f $(if ($S.Browsers.Count) { $S.Browsers -join ', ' } else { 'ninguno detectado / omitido' })))
    [void]$sb.AppendLine('')
    [void]$sb.AppendLine(('RESULTADO: RIESGO {0}  (puntaje {1}/100)' -f $risk.Label, $risk.Score))
    [void]$sb.AppendLine(('  Criticos: {0}   Medios: {1}   Info: {2}   Total: {3}' -f $risk.High, $risk.Med, @($arr | Where-Object { $_.Sev -eq 'INFO' }).Count, $arr.Count))
    [void]$sb.AppendLine('')
    foreach ($sec in @(@('HIGH', 'HALLAZGOS CRITICOS'), @('MED', 'HALLAZGOS MEDIOS'))) {
        $items = @($arr | Where-Object { $_.Sev -eq $sec[0] })
        [void]$sb.AppendLine(('--- {0} ({1}) ---' -f $sec[1], $items.Count))
        if ($items.Count -eq 0) { [void]$sb.AppendLine('  (ninguno)') }
        foreach ($f in $items) { [void]$sb.AppendLine(('  [{0}] {1}' -f $f.Cat, $f.Title)); [void]$sb.AppendLine(('        {0}' -f $f.Detail)) }
        [void]$sb.AppendLine('')
    }
    [void]$sb.AppendLine('--- ACTIVIDAD DESDE EL REINICIO ---')
    [void]$sb.AppendLine(('  Procesos iniciados          : {0}' -f $S.Counts.Proc))
    [void]$sb.AppendLine(('  Programas ejecutados        : {0}' -f $S.Counts.Exec))
    [void]$sb.AppendLine(('  Archivos nuevos / recientes : {0}' -f $S.Counts.Files))
    [void]$sb.AppendLine('')
    [void]$sb.AppendLine('--- PROGRAMAS EJECUTADOS (BAM / Prefetch, mas recientes primero) ---')
    $ex = @($S.Exec.ToArray() | Sort-Object { $_.Time } -Descending | Select-Object -First 80)
    if ($ex.Count -eq 0) { [void]$sb.AppendLine('  (sin datos - ejecuta como Administrador)') }
    foreach ($e in $ex) { [void]$sb.AppendLine(('  {0}  [{1,-8}] {2}' -f $e.Time.ToString('HH:mm:ss'), $e.Src, $e.Path)) }
    [void]$sb.AppendLine('')
    [void]$sb.AppendLine('--- PROCESOS EN EJECUCION (unicos) ---')
    $names = $S.ProcList.ToArray() | ForEach-Object { ($_ -split ' \| ')[1] } | Sort-Object -Unique
    [void]$sb.AppendLine('  ' + (($names | Select-Object -First 120) -join ', '))
    [void]$sb.AppendLine('')
    [void]$sb.AppendLine('--- CUENTAS LOGUEADAS EN NAVEGADORES ---')
    if ($S.Accounts.Count -eq 0) { [void]$sb.AppendLine('  (ninguna detectada)') }
    foreach ($a in $S.Accounts) { [void]$sb.AppendLine('  ' + $a) }
    [void]$sb.AppendLine('')
    [void]$sb.AppendLine('--- NOTA ---')
    [void]$sb.AppendLine('  Los hallazgos son indicios, no pruebas: revisalos manualmente antes de sacar conclusiones.')
    [void]$sb.AppendLine($line)
    return $sb.ToString()
}

function Update-Stats {
    $S = $script:S; $ui = $script:ui
    if (-not $S) { return }
    $arr = $S.Findings.ToArray()
    $risk = Get-Risk $arr
    $ui.StProc.Text  = [string]$S.Counts.Proc
    $ui.StExec.Text  = [string]$S.Counts.Exec
    $ui.StCrit.Text  = [string]$risk.High
    $ui.StTotal.Text = [string]$arr.Count
    $ui.StRisk.Text  = $risk.Label
    $ui.StRisk.Foreground = New-Brush $risk.Color
    $ui.StRiskSub.Text = ('puntaje {0}/100' -f $risk.Score)
}

function Update-Ui {
    $S = $script:S; $ui = $script:ui
    if (-not $S) { return }
    $ui.PBar.Width = [math]::Max(0, $ui.PTrack.ActualWidth * ($S.Progress / 100.0))
    $ui.PctText.Text = ('{0}%' -f [int]$S.Progress)
    $ui.StatusText.Text = [string]$S.Status
    $cnt = $S.Log.Count
    if ($cnt -gt $script:logIdx) {
        $sb = New-Object System.Text.StringBuilder
        for ($i = $script:logIdx; $i -lt $cnt; $i++) { [void]$sb.AppendLine([string]$S.Log[$i]) }
        $script:logIdx = $cnt
        $ui.LogBox.AppendText($sb.ToString()); $ui.LogBox.ScrollToEnd()
    }
    Update-Stats
    if ($S.Done -and -not $script:finalized) {
        $script:finalized = $true
        $script:Scanning = $false
        $ui.ScanBtn.IsEnabled = $true
        $ui.ScanBtnText.Text = 'ESCANEAR DE NUEVO'
        $ui.PBar.Width = $ui.PTrack.ActualWidth
        $ui.PctText.Text = '100%'
        $ui.StatusText.Text = 'Escaneo completado'
        Update-CatBars
        Update-Findings
        $ui.SummaryBox.Text = Build-Summary
        $script:timer.Stop()
    }
}

function Start-Scan {
    if ($script:Scanning) { return }
    $ui = $script:ui
    $script:Scanning = $true; $script:finalized = $false; $script:logIdx = 0
    $ui.ScanBtn.IsEnabled = $false; $ui.ScanBtnText.Text = 'ESCANEANDO...'
    $ui.LogBox.Clear(); $ui.CatBars.Children.Clear(); $ui.FindList.Children.Clear()
    $S = [hashtable]::Synchronized(@{})
    $S.Progress = 0; $S.Status = 'Iniciando'; $S.Done = $false; $S.Boot = $null
    $S.Cfg = $script:Cfg; $S.Admin = $script:IsAdmin
    $S.OptBrowser = [bool]$ui.BrowserToggle.IsChecked; $S.OptFiles = [bool]$ui.FilesToggle.IsChecked
    $S.Findings = [System.Collections.ArrayList]::Synchronized((New-Object System.Collections.ArrayList))
    $S.Log      = [System.Collections.ArrayList]::Synchronized((New-Object System.Collections.ArrayList))
    $S.Exec     = [System.Collections.ArrayList]::Synchronized((New-Object System.Collections.ArrayList))
    $S.ProcList = [System.Collections.ArrayList]::Synchronized((New-Object System.Collections.ArrayList))
    $S.Browsers = [System.Collections.ArrayList]::Synchronized((New-Object System.Collections.ArrayList))
    $S.Accounts = [System.Collections.ArrayList]::Synchronized((New-Object System.Collections.ArrayList))
    $S.Counts   = [hashtable]::Synchronized(@{ Proc = 0; Exec = 0; Files = 0 })
    $script:S = $S
    $rs = [runspacefactory]::CreateRunspace()
    $rs.ApartmentState = 'MTA'; $rs.Open()
    $rs.SessionStateProxy.SetVariable('S', $S)
    $ps = [powershell]::Create(); $ps.Runspace = $rs
    [void]$ps.AddScript($script:ScanScript)
    $script:ps = $ps; $script:rs = $rs
    [void]$ps.BeginInvoke()
    $script:timer.Start()
}

# --------------------------------------------------------------------------
#  APP
# --------------------------------------------------------------------------
function Build-App {
    Add-Type -AssemblyName PresentationFramework, PresentationCore, WindowsBase, System.Xaml
    if (-not ('NodeField' -as [type])) {
        Add-Type -TypeDefinition $script:NodeFieldCs -ReferencedAssemblies PresentationFramework, PresentationCore, WindowsBase, System.Xaml
    }
    $script:IsAdmin = ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
    $script:Scanning = $false; $script:finalized = $false; $script:logIdx = 0; $script:filter = 'ALL'; $script:S = $null

    $script:win = [System.Windows.Markup.XamlReader]::Load((New-Object System.Xml.XmlNodeReader ([xml]$script:Xaml)))
    $script:ui = @{}
    foreach ($m in [regex]::Matches($script:Xaml, 'x:Name="([^"]+)"')) {
        $n = $m.Groups[1].Value
        $el = $script:win.FindName($n)
        if ($el) { $script:ui[$n] = $el }
    }
    $ui = $script:ui

    # logo
    $bytes = [Convert]::FromBase64String($script:LogoB64)
    $ms = New-Object System.IO.MemoryStream (, $bytes)
    $bi = New-Object System.Windows.Media.Imaging.BitmapImage
    $bi.BeginInit(); $bi.StreamSource = $ms; $bi.CacheOption = 'OnLoad'; $bi.EndInit(); $bi.Freeze()
    $ui.LogoSide.Source = $bi; $ui.LogoHero.Source = $bi
    try { $script:win.Icon = $bi } catch { }

    # campo de particulas
    $script:field = New-Object NodeField
    [void]$ui.FieldHost.Children.Add($script:field)
    $ui.FieldHost.Clip = [System.Windows.Media.RectangleGeometry]::new([System.Windows.Rect]::new(0, 0, 1438, 898), 21, 21)

    # escala para pantallas chicas
    $wa = [System.Windows.SystemParameters]::WorkArea
    $sc = [math]::Min(1.0, [math]::Min($wa.Width / 1460.0, $wa.Height / 930.0))
    if ($sc -lt 1.0) {
        $ui.Scaler.LayoutTransform = New-Object System.Windows.Media.ScaleTransform -ArgumentList $sc, $sc
        $script:win.Width = 1440 * $sc; $script:win.Height = 900 * $sc
    }

    Set-Theme $true

    # info
    try { $boot = (Get-CimInstance Win32_OperatingSystem).LastBootUpTime; $ui.BootText.Text = $boot.ToString('dd/MM  HH:mm') } catch { $boot = $null }
    $ui.PcText.Text = ('{0} · {1}' -f $env:COMPUTERNAME, $env:USERNAME)
    if ($script:IsAdmin) { $ui.AdminText.Text = 'ADMINISTRADOR' } else { $ui.AdminText.Text = 'SIN ADMIN · RESULTADOS PARCIALES'; $ui.AdminText.Foreground = New-Brush '#FFB84D' }
    $ui.SysInfo.Text = ("PXTDETECTED.IA v{0}`nPowerShell {1} · {2}`nAdministrador: {3}`nTip: para un escaneo completo (BAM, Prefetch, eventos) abrí PowerShell como Administrador." -f $script:AppVer, $PSVersionTable.PSVersion, [Environment]::OSVersion.VersionString, $(if ($script:IsAdmin) { 'Sí' } else { 'No' }))
    $ui.LogBox.Text = "Listo. Presioná INICIAR ESCANEO para analizar la PC desde el último reinicio.`r`n"

    # eventos
    $script:timer = New-Object System.Windows.Threading.DispatcherTimer
    $script:timer.Interval = [TimeSpan]::FromMilliseconds(200)
    $script:timer.Add_Tick({ Update-Ui })

    $ui.NavDash.Add_Checked({ Show-Page 'Dash' })
    $ui.NavFind.Add_Checked({ Show-Page 'Find'; Update-Findings })
    $ui.NavSum.Add_Checked({ Show-Page 'Sum' })
    $ui.NavSet.Add_Checked({ Show-Page 'Set' })
    $ui.BtnToSum.Add_Click({ $script:ui.NavSum.IsChecked = $true })
    $ui.ScanBtn.Add_Click({ Start-Scan })
    $ui.BtnMin.Add_Click({ $script:win.WindowState = 'Minimized' })
    $ui.BtnClose.Add_Click({ $script:win.Close() })
    $ui.FAll.Add_Checked({ $script:filter = 'ALL'; Update-Findings })
    $ui.FHigh.Add_Checked({ $script:filter = 'HIGH'; Update-Findings })
    $ui.FMed.Add_Checked({ $script:filter = 'MED'; Update-Findings })
    $ui.FInfo.Add_Checked({ $script:filter = 'INFO'; Update-Findings })
    $ui.ThemeToggle.Add_Checked({ Set-Theme $true })
    $ui.ThemeToggle.Add_Unchecked({ Set-Theme $false })
    $ui.PartToggle.Add_Checked({ $script:field.Visibility = 'Visible' })
    $ui.PartToggle.Add_Unchecked({ $script:field.Visibility = 'Collapsed' })
    $ui.BtnCopy.Add_Click({ try { [System.Windows.Clipboard]::SetText($script:ui.SummaryBox.Text); $script:ui.ExportMsg.Text = 'Copiado al portapapeles.' } catch { } })
    $ui.BtnExport.Add_Click({
        try {
            $f = Join-Path ([Environment]::GetFolderPath('Desktop')) ('PXTDETECTED_Reporte_{0}.txt' -f (Get-Date -Format 'yyyyMMdd_HHmmss'))
            Set-Content -Path $f -Value $script:ui.SummaryBox.Text -Encoding UTF8
            $script:ui.ExportMsg.Text = 'Guardado en el Escritorio: ' + (Split-Path $f -Leaf)
        } catch { $script:ui.ExportMsg.Text = 'No se pudo guardar el reporte.' }
    })
    $script:win.Add_MouseLeftButtonDown({
        param($s, $e)
        $p = $e.GetPosition($script:ui.Shell)
        if ($p.Y -lt 64 -or $p.X -lt 274) { try { $script:win.DragMove() } catch { } }
    })
    $script:win.Add_Closed({ try { if ($script:ps) { $script:ps.Stop(); $script:ps.Dispose() }; if ($script:rs) { $script:rs.Close() } } catch { } })
}

function Start-PXT {
    $Host.UI.RawUI.WindowTitle = 'PXTDETECTED.IA'
    if ([Environment]::OSVersion.Platform -ne 'Win32NT') { Write-Host 'PXTDETECTED.IA solo funciona en Windows.' -ForegroundColor Red; return }
    Show-PorteBanner
    if (-not (Test-PorteKey)) { return }
    if ([Threading.Thread]::CurrentThread.GetApartmentState() -ne 'STA') {
        Write-Host '   [ERROR] Abri Windows PowerShell 5.1 (powershell.exe) - se necesita modo STA.' -ForegroundColor Red
        return
    }
    try {
        Build-App
        [void]$script:win.ShowDialog()
    } catch {
        Write-Host ('   [ERROR] ' + $_.Exception.Message) -ForegroundColor Red
    }
}

Start-PXT
